export const makeMetaQuery = (query) => {
	const { value } = query;

	// if (query.operator === 'LIKE' || query.operator === 'NOT_LIKE') {
	// 	value = `%${value}%`;
	// }

	return {
		meta_key: query.filter,
		meta_value: value,
		compare: query.operator,
	};
};

export const getCompareValue = (compare) => {
	switch (compare) {
		case 'equal':
			return '=';
		case 'not_equal':
			return '!=';
		case 'contain':
			return 'LIKE';
		case 'not_contain':
			return 'NOT LIKE';
		default:
			return '=';
	}
};
