import moment from 'moment';
const i18n = window.fvGlobalVar?.i18n;
const { settings_saved: settingsSaved } = window.fvGlobalVar;
const FV_LAUNCH_DATE = '2019-05-29';

export const setQueryParams = () => ({
	per_page: 10,
	page_num: 1,
	...getFormsData(),
	...getDateData(),
	...getQueryFilters(),
	...getFilterType(),
});

export const setToLocalStorage = (key, data) => {
	if (!settingsSaved?.persist_filter) {
		clearLocalStorage();
		return;
	}
	window.localStorage.setItem(key, JSON.stringify(data));
};

export const getFromLocalStorage = (key) => {
  const data = JSON.parse(window.localStorage.getItem(key));
  if(data){
    return data;
  }
  return null;
}
	

export const deleteFromLocalStorage = (key) =>
	window.localStorage.removeItem(key);

export const clearLocalStorage = (force = false) => {
	if (!settingsSaved?.persist_filter || force) {
		const fvKeys = ['fv-form', 'fv-chart-type','fv-analytics-filter', 'fv-filters', 'fv-date-range'];
		fvKeys.forEach((key) => localStorage.removeItem(key));
	}
};

const getFilterType = () => {
	const localSavedFilter = getFromLocalStorage('fv-analytics-filter');

	if (localSavedFilter) {
		return {
			filter_type: localSavedFilter,
		};
	}

	return {
		filter_type: 'month',
	};
};

const getFormsData = () => {
	const localSavedForm = getFromLocalStorage('fv-form');

	if (localSavedForm) {
		return {
			formid: localSavedForm?.value || '',
			plugin: localSavedForm?.plugin || '',
		};
	}

	return {
		formid: '',
		plugin: '',
	};
};

const getDateData = () => {
	const savedDateData = getFromLocalStorage('fv-date-range');

	if (savedDateData) {
		return {
			query_type: savedDateData.queryType,
			fromDate: savedDateData.fromDate,
			toDate: savedDateData.toDate,
		};
	}

	return {
		query_type: 'This_Year',
		fromDate: '',
		toDate: '',
	};
};

const getQueryFilters = () => {
	const savedFiltersData = getFromLocalStorage('fv-filters');
	if (savedFiltersData) {
		return {
			query_filters: savedFiltersData.filters,
			filter_relation: savedFiltersData.filterRelation,
			status: savedFiltersData.status,
			selectedStatus: savedFiltersData.selectedStatus,
		};
	}
	return {
		query_filters: [
			{
				filter: '',
				key: 'contain',
				operator: 'LIKE',
				value: '',
			},
		],
		filter_relation: 'OR',
		status: [],
		selectedStatus: [],
	};
};

export const getSideBarData = () => {
	const savedSidebarData = getFromLocalStorage('fv-sidebar');

	if (savedSidebarData) {
		return {
			width: savedSidebarData.width,
			height: savedSidebarData.height,
		};
	}

	return {
		width: '50%',
		height: '50%',
	};
};

export const shortcuts = [
    {
      text: i18n.today,
      value: () => {
        const start = moment();
        const end = moment();
        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.yesterday,
      value: () => {
        const start = moment().subtract(1, 'day');
        const end = moment().subtract(1, 'day');
        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.this_week,
      value: () => {
        const start = moment().startOf('isoWeek');
        const end = moment().endOf('isoWeek');
        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.last_week,
      value: () => {
        const start = moment().startOf('isoWeek').subtract(1, 'week');
        const end = moment().endOf('isoWeek').subtract(1, 'week');

        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.last_30_days,
      value: () => {
        const start = moment().subtract(29, 'days');
        const end = moment();

        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.this_month,
      value: () => {
        const start = moment().startOf('month');
        const end = moment().endOf('month');

        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.last_month,
      value: () => {
        const start = moment().subtract(1, 'month').startOf('month');
        const end = moment().subtract(1, 'month').endOf('month');

        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.this_quarter,
      value: () => {
        const start = moment().startOf('quarter');
        const end = moment().endOf('quarter');

        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.last_quarter,
      value: () => {
        const start = moment().quarter(moment().quarter() - 1).startOf('quarter');
        const end = moment().quarter(moment().quarter() - 1).endOf('quarter');

        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.this_year,
      value: () => {
        const start = moment().startOf('year');
        const end = moment().endOf('year');

        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.last_year,
      value: () => {
        const start = moment().startOf('year').subtract(1, 'year');
        const end = moment().endOf('year').subtract(1, 'year');

        return [start, end]
      },
      active: false,
    },
    {
      text: i18n.all_time,
      value: () => {
        const end = moment();
        const start = moment(FV_LAUNCH_DATE);

        return [start, end]
      },
      active: false,
    },
  ];