import { ref, watch } from 'vue'
import { defineStore } from 'pinia'
import  axios  from "axios";
import {axiosPost} from "../Axios/post";
import { setQueryParams, getSideBarData, setToLocalStorage, getFromLocalStorage, shortcuts } from './utils';
import { makeMetaQuery, prepareReactTableData } from '../Components/Submissions/utils';
import Delete from '../Components/Submissions/notes/delete.vue';
import { ElNotification } from 'element-plus';

const default_end = new Date();
const default_start = new Date();
default_start.setTime(default_start.getTime() - 3600 * 1000 * 24 * 555)
const dateRange = getFromLocalStorage('fv-date-range');

let default_start_string = dateRange?.fromDate || `${default_start.getFullYear()}-${default_start.toLocaleString('default', { month: '2-digit' })}-${default_start.toLocaleString('default', { day: '2-digit' })}`;
let default_end_string = dateRange?.toDate || `${default_end.getFullYear()}-${default_end.toLocaleString('default', { month: '2-digit' })}-${default_end.toLocaleString('default', { day: '2-digit' })}`;

if(dateRange?.queryType !== 'Custom'){
    const queryType = dateRange?.queryType || 'This_Year';
    //console.log('queryType', queryType);

    const shortcut = shortcuts.filter((p) => p.text === queryType.replaceAll('_', ' '))[0];
    default_start_string = shortcut.value()[0].format('YYYY-MM-DD');
    default_end_string = shortcut.value()[1].format('YYYY-MM-DD');
}


const {
    user_capability: userCapability,
    settings_saved: settingsSaved,
    entry_table_fields: entryTableFields,
} = window.fvGlobalVar;
export const useFVStore = defineStore('formVibes', {
    state: () => ({
        isLoading: false,
        isSaving: false,
        dates: [default_start_string, default_end_string],
        defaultDates:[default_start_string, default_end_string],
        analyticsStates: {
            chartData: {
                data: {},
                options: {},
            },
        },
        generalStates: {
            isPro: window.fvGlobalVar.is_pro == '1',
            loading: true,
            forms: window.fvGlobalVar.forms,
            columns: [],
            subComponentColumns: [],
            selectedRowsId: [],
            queryParams: setQueryParams(),
            subComponentData: [],
            size: getSideBarData(),
            isNoPlugins: !Object.keys(window.fvGlobalVar.plugins).length,
        },
        notes:{},
        notice: {
            isError: false,
            isSuccess: false,
            message: '',
        },
        data: [],
        exportProfileData: window.fv_export_profiles_data,
        fvDataProfile: window?.fvdata || [],
        columns: [],
        // tableData: [],
        isDisabled: false,
        submissionCount : '',
        isEditable: false,
        currentForm : getFromLocalStorage('fv-form')?.value || '',
        currentPlugin : getFromLocalStorage('fv-form')?.plugin || '',
        settings: settingsSaved,
        preset: getFromLocalStorage('fv-date-range')?.queryType || 'custom',
    }),
    getters: {
        formsSelector: (state) => {
            const formsData = [];
            Object.entries(state.generalStates.forms).forEach(([pluginName, forms]) => {
                if (Object.keys(forms)?.length > 0) {
                    formsData.push({
                        label: pluginName,
                        options: Object.values(forms)?.map((form) => ({
                            label: `${form.name}${
                                settingsSaved?.debug_mode ? `(${form.id})` : ''
                            }`,
                            value: form.id.toString(),
                            plugin: pluginName,
                        })),
                    });
                }
            });
    
            return formsData;
        },
        isPro:(state) => {
            return state.generalStates.isPro;
        },
        isNoPlugins: (state) => { return !Object.keys(window.fvGlobalVar.plugins).length },
        selectedRowsId: (state) => { return state.generalStates.selectedRowsId },
        tableData: (state) => {
            return state.data.data || [];
        },
        formColumns: (state) => {
            return state.data.columns || [];
        },
        tableColumns: (state) => {
            // if(state.columns.length === 0){
            //     return [];
            // }
           const col = state.columns
				.filter((col) => col.visible)
				.filter((col) => {
					if (false) {
						return entryTableFields.includes(col.colKey);
					}
					return true;
				})
				.map((col) => ({
                    key: col.colKey,
                    dataKey: col.colKey,
                    title: col.alias,
                    width: 200,
				}));

                return col;
        },
        isEditEnable: (state) => {
            return state.isEditable;
        },
        isAllRowSelected:(state) => {
            return state.data?.data?.length === state.selectedRowsId.length;
        },
        size: (state) => { return state.generalStates.size; },
        pageSizes: (state) => {
            const { table_size_limits: limits } = window.fvGlobalVar;

            return limits.map((limit) => limit.key)
        }

    },
    actions: { 
        setLoading(loading) {
            this.isLoading = loading;
        },
        setNotes(notes) {
            this.notes = {
                ...this.notes,
                notes
            }
        },
        async fetchData(params){
            const queryParams = this.generalStates.queryParams;
            this.isLoading = true;
            
            const metaQuery = queryParams?.query_filters
			?.filter((filter) => filter.filter !== '')
			?.map((filter) => makeMetaQuery(filter));
            
            const formId = queryParams.formid;
            const plugin = queryParams.plugin;
            const { data } = await axiosPost({
                queryParams: {
                    limit: queryParams.per_page,
                    form_id: formId,
                    plugin: plugin,
                    status: queryParams.selectedStatus,
                    from_date: this.dates[0] || '',
                    to_date: this.dates[1] || '',
                    current_page: queryParams.page_num,
                    meta_query: { relation: queryParams.filter_relation, ...metaQuery },
                },
            });
            if(data.is_error ){
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: data.message,
                };
                this.isLoading = false;
                return;
            }
            
            this.data = data;
            
            this.columns = data.columns;
            const rtData = prepareReactTableData(data, queryParams.per_page);

            // this.tableData = rtData;
            this.isDisabled = rtData.totalPageCount <= 0;
            this.submissionCount = data.total_submission_count;
            
            this.isLoading = false;
            //console.log('query param data ', queryParams);
            // setToLocalStorage('fv-date-range', {
            //     toDate: this.dates[1] || '',
            //     fromDate: this.dates[0] || '',
            //     queryType: this.generalStates.queryParams.query_type,
            // });
        },
        updateColumns(columns){
            // not using this function currently anywhere
            this.columns = columns;
        },
        updateSetting(data) {
            this.settings = data;
        },
        async updateStatus(status, row, source = 'row') {
            let ids = [];
            if(source === 'row'){
                ids.push(row.id);
                if (status === row.fv_status) {
                    return;
                }
            }
            else{
                ids = this.selectedRowsId;
            }

            this.isSaving = true;

            try {
                const { data } = await axiosPost({
                    action: 'fv_set_submission_status',
                    queryParams: {
                        row_ids: ids,
                        status_key: status,
                    },
                });
                if (data.is_error) {
                    throw new Error(data.message);
                }
    
                this.resetError();

                this.notice = {
                    ...this.notice,
                    isSuccess: true,
                    message: data.message,
                };

                ids.forEach((id) => {
                    const index = this.data.data.findIndex((e) => e.id === id);
                
                    this.data.data[index].fv_status = status;
                })
                
                
            } catch (error) {
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: error.message,
                };
            } finally {
                this.isSaving = false;
            }

        },
        async upldateColumnData(row,colKey, value){
            let plugin = '';
            let formid = '';
            const form = getFromLocalStorage('fv-form')
            if(form == null){
                plugin = this.generalStates.queryParams.plugin;
                formid = this.generalStates.queryParams.formid;
            }else{
                plugin = form.plugin;
                formid = form.value;
            }
            this.isSaving = true;
            try {
                const { data } = await axiosPost({
                    action: 'fv_update_submission',
                    queryParams: {
                        updateInfo: {
                            dataId: row.id,
                            columnId: colKey,
                            newValue: row[colKey],
                            prevValue: value, // we don't need previous value
                            currentForm: formid,
                            currentPlugin: plugin
                        },
                    },
                });
                if (data.is_error) {
                    throw new Error(data.message);
                }
    
                this.resetError();
    
                this.notice = {
                    ...this.notice,
                    isSuccess: true,
                    message: data.message,
                };
                // setValue(value);
            } catch (error) {
                // setValue(initialValue);
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: error.message,
                }
            } finally {
                this.isSaving = false;
            }
        },
        async deteleRows(){
            this.isSaving = true;
            try {
                const { data } = await axiosPost({
                    queryParams: {
                        ids: this.selectedRowsId,
                    },
                    action: 'fv_delete_submissions',
                });
                if (data.is_error) {
                    throw new Error(data.message);
                }

                this.resetError();
                
                if (this.isAllRowSelected) {
                    if (this.generalStates.queryParams.page_num === 1) {
                        this.fetchData();
                    } else {
                        const pageNumber = this.generalStates.queryParams.page_num;
                        this.generalStates= {
                            ...this.generalStates,
                            queryParams: {
                                ...this.generalStates.queryParams,
                                page_num: pageNumber - 1,
                            }
                        }
                    }
                } else {
                    this.fetchData();
                }
                this.notice = {
                    ...this.notice,
                    isSuccess: true,
                    message: data.message,
                }
            } catch (error) {
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: error.message,
                }
            }
            finally{
                this.isSaving = false;
            }
        },
        resetError(){
            this.notice = {
                ...this.notice,
                isError: false,
			    message: '',
            }
        },
        async addNote(id,noteText){
            this.isSaving = true;
            try {
                
                const { data } = await axiosPost({
                    action: 'fv_set_note',
                    queryParams: {
                        entryId: id,
                        note: noteText,
                    },
                });    
                
                if (data.is_error) {
                    throw new Error(data.message);
                }
    
                this.resetError();
    
                this.notice = {
                    ...this.notice,
                    isSuccess: true,
                    message: data.message,
                }
                this.notes = {
                    ...this.notes,
                    [id]: [{ ...data.data }, ...this.notes[id]],
                }
            } catch (error) {
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: error.message,
                }
            } finally {
                this.isSaving = false;
            }
        },
        async saveSettings(params){
            this.isSaving = true;
            try {
                const { data } = await axiosPost({
                    queryParams: params,
                    action: 'fv_save_settings',
                });
                
                if (data.is_error) {
                    throw new Error(data.message);
                }
                this.updateSetting(params);
                this.resetError();
                this.notice = {
                    ...this.notice,
                    isSuccess: true,
                    message: 'Settings saved successfully!',
                };
                
            } catch (error) {
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: error.message,
                };
            } finally {
                this.isSaving = false
            }
        },
        async saveRoles(capabilities){
            this.isSaving = true
            try {
                const { data } = await axiosPost({
                    queryParams: {
                        capabilities,
                    },
                    action: 'fv_save_capabilities',
                });
                if (data.is_error) {
                    throw new Error(data.message);
                }
                this.resetError();
                this.notice = {
                    ...this.notice,
                    isSuccess: true,
                    message: 'Settings saved successfully!',
                };
            } catch (error) {
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: error.message,
                };
            } finally {
                this.isSaving = false;
            }
        },
        async DeleteNote(row,index,length){
            let noteIndex = length - index - 1;
            try{
                const {data} = await axiosPost({
                    queryParams: {
                        entry_id: row,
                        index: noteIndex,
                    },
                    action: 'fv_delete_notes',
                });
                if (data.is_error) {
                    throw new Error(data.message);
                }
                this.notes[row].splice(index, 1);
                this.notice = {
                    ...this.notice,
                    isSuccess: true,
                    message: data.message,
                }
            }catch(error){
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: error.message,
                }
            }

            // remove note with index from notes
            
        },
        async resetSettings(){
            this.isSaving = true;
            try {
                const { data } = await axiosPost({
                    action: 'fv_reset_settings',
                });
                if (data.is_error) {
                    throw new Error(data.message);
                }
                this.resetError();
                this.notice = {
                    ...this.notice,
                    isSuccess: true,
                    message: 'Settings reset successfully!',
                };
            } catch (error) {
                this.notice = {
                    ...this.notice,
                    isError: true,
                    message: error.message,
                };
            } finally {
                this.isSaving = false;
            }
        }
    }
});